package portscan

import (
	"net/netip"
	"os"
	"path/filepath"
	"sort"
	"testing"
	"time"
)

// The differential harness.
//
// Ordinary expectation tests assert that the code produces the output the
// author expected -- but the same misconception shapes both the code and the
// expectation, so they agree and the bug ships. This harness answers a harder
// question: given traffic produced by the real tool, does the engine name the
// technique that tool was actually asked to use?
//
// The two sides are computed independently:
//
//   - one side is the corpus, generated by running real nmap against a real
//     interface (testdata/generate_corpus.sh). Ground truth is the nmap option
//     on the command line, recorded in the file name;
//   - the other side is this package's verdict on the captured bytes.
//
// Neither side can borrow the other's mistakes: nothing in the corpus was
// produced by code in this package.

// corpusVictim4/6 must match the addresses in generate_corpus.sh. The engine
// only counts packets aimed at one of the host's own unicast addresses, so
// setting these correctly is also what makes the replay discard the victim's
// own outbound replies -- exactly as a TC ingress hook would.
var (
	corpusVictim4 = netip.MustParseAddr("10.77.0.1")
	corpusVictim6 = netip.MustParseAddr("fd00:77::1")
)

func corpusDir() string { return filepath.Join("testdata", "pcap") }

// corpusHost is the HostInfo used for replay: nothing listens, nothing is
// exempt, no connection is known, and only the two victim addresses are ours.
type corpusHost struct{}

func (corpusHost) IsLocalUnicast(a netip.Addr) bool { return a == corpusVictim4 || a == corpusVictim6 }
func (corpusHost) IsListening(uint8, uint16) bool   { return false }
func (corpusHost) HasConnection(*Probe) bool        { return false }
func (corpusHost) IsOnLink(netip.Addr) bool         { return true }
func (corpusHost) IsExempt(netip.Addr) bool         { return false }

// replayResult is what a corpus file produced.
type replayResult struct {
	packets  int
	probes   int
	events   []*ScanEvent
	byMethod map[ScanMethod]int
	sources  map[netip.Addr]bool
}

// replay feeds a capture through a fresh engine.
func replay(t *testing.T, path string, cfg Config, timeScale float64) *replayResult {
	t.Helper()
	f, err := readPcap(path)
	if err != nil {
		t.Fatalf("readPcap(%s): %v", path, err)
	}
	probes, err := f.probesFrom(uint64(time.Hour), timeScale)
	if err != nil {
		t.Fatalf("probesFrom(%s): %v", path, err)
	}
	// Alert rate limiting and the per-source cooldown exist to protect a
	// human's notification tray; here they would hide verdicts. They have
	// their own dedicated tests.
	cfg.AlertsPerMinute = maxAlertsPerMinute
	cfg.ReportCooldown = 0
	cfg.StartupGrace = 0

	e, err := NewEngine(cfg, corpusHost{}, 0)
	if err != nil {
		t.Fatalf("NewEngine: %v", err)
	}
	res := &replayResult{
		packets:  len(f.Packets),
		probes:   len(probes),
		byMethod: map[ScanMethod]int{},
		sources:  map[netip.Addr]bool{},
	}
	for _, p := range probes {
		if ev := e.Process(p); ev != nil {
			res.events = append(res.events, ev)
			res.byMethod[ev.Method]++
			res.sources[ev.Src] = true
		}
	}
	return res
}

// firstEvent returns the first emitted event, or nil.
func (r *replayResult) firstEvent() *ScanEvent {
	if len(r.events) == 0 {
		return nil
	}
	return r.events[0]
}

// corpusCase ties a capture to the verdict its generating command implies.
type corpusCase struct {
	file string
	// wantDetected is whether a scan must be reported at all.
	wantDetected bool
	// wantMethod is the technique the nmap option used implies. Zero value
	// (MethodUnknown) means "do not assert the method", used where the option
	// legitimately produces several probe families.
	wantMethod ScanMethod
	// wantProtocolScan requires the IP-protocol-scan flag to be set.
	wantProtocolScan bool
	// note documents why the expectation is what it is.
	note string
}

// corpusCases is the oracle. Each expectation is derived from the nmap manual's
// description of the option used to generate the file, never from this
// package's behaviour.
var corpusCases = []corpusCase{
	{file: "tcp-syn", wantDetected: true, wantMethod: MethodSYN,
		note: "nmap -sS sends bare SYNs"},
	{file: "tcp-connect", wantDetected: true, wantMethod: MethodSYN,
		note: "nmap -sT uses connect(2); on the wire the probe is still a bare SYN"},
	{file: "tcp-fin", wantDetected: true, wantMethod: MethodFIN,
		note: "nmap -sF sets FIN only"},
	{file: "tcp-null", wantDetected: true, wantMethod: MethodNULL,
		note: "nmap -sN sets no control bits"},
	{file: "tcp-xmas", wantDetected: true, wantMethod: MethodXmas,
		note: "nmap -sX sets FIN, PSH and URG"},
	{file: "tcp-maimon", wantDetected: true, wantMethod: MethodMaimon,
		note: "nmap -sM sets FIN and ACK"},
	{file: "tcp-ack", wantDetected: true, wantMethod: MethodACK,
		note: "nmap -sA sends a bare ACK"},
	{file: "tcp-window", wantDetected: true, wantMethod: MethodACK,
		note: "nmap -sW sends the SAME bare ACK as -sA; the two differ only in how the scanner reads the returned window, so reporting anything more specific would be a fabrication"},
	{file: "tcp-custom-flags", wantDetected: true, wantMethod: MethodCustomFlags,
		note: "nmap --scanflags PSHURG is not one of the named techniques"},
	{file: "tcp-synfin", wantDetected: true, wantMethod: MethodSYNFIN,
		note: "nmap --scanflags SYNFIN"},
	{file: "udp", wantDetected: true, wantMethod: MethodUDP,
		note: "nmap -sU sends UDP datagrams with no flags to name"},
	{file: "ip-protocol", wantDetected: true, wantProtocolScan: true,
		note: "nmap -sO varies the IP protocol number; it also emits real TCP and UDP headers, so the method is legitimately mixed and only the protocol-scan flag is asserted"},

	{file: "tcp-syn-v6", wantDetected: true, wantMethod: MethodSYN,
		note: "same technique over IPv6"},
	{file: "tcp-fin-v6", wantDetected: true, wantMethod: MethodFIN},
	{file: "tcp-xmas-v6", wantDetected: true, wantMethod: MethodXmas},
	{file: "udp-v6", wantDetected: true, wantMethod: MethodUDP},

	{file: "tcp-syn-decoy", wantDetected: true,
		note: "nmap -D forges extra sources; the scan is fully visible but the real origin is not recoverable, so only detection is asserted"},
	{file: "tcp-os-fingerprint", wantDetected: true,
		note: "nmap -O mixes a port scan with fingerprinting probes"},
	{file: "tcp-syn-fragmented", wantDetected: true, wantMethod: MethodFragmentedTCP,
		note: "nmap -f splits the TCP header across IP fragments so the flag octet is never in the first fragment. The destination ports ARE present there, so the scan is detectable; the technique behind it is not, and reporting MethodNULL for flags that were never read would be a fabrication"},
	{file: "tcp-syn-slow", wantDetected: true, wantMethod: MethodSYN,
		note: "nmap -T1 waits 15s between probes, which is well inside the limit Config.SlowestDetectableScan reports for system-port SYNs; a fixed-window detector like scanlogd's 3-second window would miss it entirely"},

	{file: "benign-single-port", wantDetected: false,
		note: "repeated attempts to ONE closed port are an application failing to reach a stopped service, not a scan; counting them is the mistake PortSentry and flowhawk make"},
}

// TestDifferentialCorpus is the core of the harness.
func TestDifferentialCorpus(t *testing.T) {
	requireCorpus(t)
	for _, tc := range corpusCases {
		t.Run(tc.file, func(t *testing.T) {
			path := filepath.Join(corpusDir(), tc.file+".pcap")
			if _, err := os.Stat(path); err != nil {
				corpusSkipf(t, "corpus file missing: %v (run testdata/generate_corpus.sh)", err)
			}
			res := replay(t, path, testConfig(), 1.0)
			if res.probes == 0 {
				t.Fatalf("%s: no parseable probe out of %d captured packets", tc.file, res.packets)
			}

			got := res.firstEvent()
			if tc.wantDetected && got == nil {
				t.Fatalf("%s: no scan reported (%d probes). %s", tc.file, res.probes, tc.note)
			}
			if !tc.wantDetected {
				if got != nil {
					t.Fatalf("%s: reported as a scan but must not be. %s\n  method=%v ports=%d score=%d",
						tc.file, tc.note, got.Method, got.DistinctPorts, got.Score)
				}
				return
			}
			if tc.wantMethod != MethodUnknown && got.Method != tc.wantMethod {
				t.Errorf("%s: method = %v (%s), want %v. %s",
					tc.file, got.Method, got.MethodDetail, tc.wantMethod, tc.note)
			}
			if tc.wantProtocolScan && !got.IsProtocolScan {
				t.Errorf("%s: IsProtocolScan not set (saw %d distinct protocols). %s",
					tc.file, got.Protocols, tc.note)
			}
			if got.Src == corpusVictim4 || got.Src == corpusVictim6 {
				t.Errorf("%s: reported the victim's own address %v as the scanner; outbound replies leaked into detection", tc.file, got.Src)
			}
			if got.DistinctPorts == 0 && !got.IsProtocolScan {
				t.Errorf("%s: reported a port scan with zero distinct ports", tc.file)
			}
			t.Logf("%s: %d packets -> %d probes -> %v (%s), ports=%d [%d..%d], score=%d, flags=%s",
				tc.file, res.packets, res.probes, got.Method, got.MethodDetail,
				got.DistinctPorts, got.MinPort, got.MaxPort, got.Score, got.FlagsSummary)
		})
	}
}

// TestDifferentialHarnessCanFail is the guard the harness itself needs.
//
// A comparison harness that silently compares nothing passes just as happily
// as a correct one. This test deliberately breaks the input -- it strips every
// TCP control bit, turning every technique into a NULL scan -- and requires
// the harness to notice. If this test ever passes while TestDifferentialCorpus
// also passes on mutated data, the harness is not actually checking anything.
func TestDifferentialHarnessCanFail(t *testing.T) {
	requireCorpus(t)
	path := filepath.Join(corpusDir(), "tcp-xmas.pcap")
	if _, err := os.Stat(path); err != nil {
		corpusSkipf(t, "corpus file missing: %v", err)
	}
	f, err := readPcap(path)
	if err != nil {
		t.Fatalf("readPcap: %v", err)
	}
	probes, err := f.probesFrom(uint64(time.Hour), 1.0)
	if err != nil {
		t.Fatalf("probesFrom: %v", err)
	}
	cfg := testConfig()
	cfg.AlertsPerMinute = maxAlertsPerMinute
	e, err := NewEngine(cfg, corpusHost{}, 0)
	if err != nil {
		t.Fatalf("NewEngine: %v", err)
	}
	var ev *ScanEvent
	for _, p := range probes {
		p.TCPFlags = 0 // the mutation
		if got := e.Process(p); got != nil && ev == nil {
			ev = got
		}
	}
	if ev == nil {
		t.Fatal("mutated corpus produced no event at all; the harness cannot distinguish anything")
	}
	if ev.Method == MethodXmas {
		t.Fatal("harness reported an Xmas scan for packets whose flags were all cleared: it is not reading the flags")
	}
	if ev.Method != MethodNULL {
		t.Fatalf("mutated corpus reported as %v, want MethodNULL", ev.Method)
	}
}

// TestSlowScanReplay stretches a real capture's timestamps to reproduce a slow
// scan without spending ten minutes capturing one.
//
// It pins the boundary that Config.SlowestDetectableScan computes: a scan
// slower than that figure is not reported within an hour, if at all, and the
// project documents it rather than pretending otherwise.
func TestSlowScanReplay(t *testing.T) {
	requireCorpus(t)
	path := filepath.Join(corpusDir(), "tcp-syn.pcap")
	if _, err := os.Stat(path); err != nil {
		corpusSkipf(t, "corpus file missing: %v", err)
	}
	f, err := readPcap(path)
	if err != nil {
		t.Fatalf("readPcap: %v", err)
	}
	probes, err := f.probesFrom(0, 1.0)
	if err != nil {
		t.Fatalf("probesFrom: %v", err)
	}
	// Re-time the inbound probes to an exact, chosen spacing, so the test
	// asserts the engine's behaviour rather than the capture's jitter.
	inbound := probes[:0:0]
	for _, p := range probes {
		if p.Dst == corpusVictim4 {
			inbound = append(inbound, p)
		}
	}
	if len(inbound) < 20 {
		t.Fatalf("only %d inbound probes in the capture", len(inbound))
	}

	run := func(gap time.Duration) bool {
		cfg := testConfig()
		cfg.AlertsPerMinute = maxAlertsPerMinute
		e, err := NewEngine(cfg, corpusHost{}, 0)
		if err != nil {
			t.Fatalf("NewEngine: %v", err)
		}
		for i, p := range inbound {
			q := *p
			q.TimeNs = uint64(i) * uint64(gap)
			if ev := e.Process(&q); ev != nil {
				return true
			}
		}
		return false
	}

	cfg := testConfig()
	limit := cfg.SlowestDetectableScan(ProbeWeight(PortSystem, multSynClosed))
	t.Logf("configured slowest detectable scan for system-port SYNs: %v", limit)

	if !run(limit / 4) {
		t.Errorf("a scan four times faster than the documented limit (%v) was not detected", limit/4)
	}
	if run(limit * 4) {
		t.Errorf("a scan four times slower than the documented limit (%v) was detected; the documented limit is wrong", limit*4)
	}
}

// TestCorpusSourceMACIsCaptured proves the capture really carries layer 2, so
// the MAC reported to the user is a real observation and not a placeholder.
// PortSentry cannot do this at all: its AF_PACKET/SOCK_DGRAM sockets strip the
// Ethernet header (sentry_stealth.c:59-67).
func TestCorpusSourceMACIsCaptured(t *testing.T) {
	requireCorpus(t)
	path := filepath.Join(corpusDir(), "tcp-syn.pcap")
	if _, err := os.Stat(path); err != nil {
		corpusSkipf(t, "corpus file missing: %v", err)
	}
	res := replay(t, path, testConfig(), 1.0)
	ev := res.firstEvent()
	if ev == nil {
		t.Fatal("no scan detected")
	}
	if !ev.HasMAC {
		t.Fatal("no source MAC recovered from an Ethernet capture")
	}
	if ev.SrcMAC == ([6]byte{}) {
		t.Fatal("source MAC is all zeroes")
	}
	if !ev.MACIsSourceOwn {
		t.Error("MACIsSourceOwn not set although the corpus source is on-link")
	}
	t.Logf("source MAC observed: %02x:%02x:%02x:%02x:%02x:%02x",
		ev.SrcMAC[0], ev.SrcMAC[1], ev.SrcMAC[2], ev.SrcMAC[3], ev.SrcMAC[4], ev.SrcMAC[5])
}

// TestDecoyScanReportsSeveralSources documents the security consequence of
// nmap -D: every forged decoy looks exactly like a genuine scanner, so
// automatic blocking would take out whatever addresses the attacker chose.
func TestDecoyScanReportsSeveralSources(t *testing.T) {
	requireCorpus(t)
	path := filepath.Join(corpusDir(), "tcp-syn-decoy.pcap")
	if _, err := os.Stat(path); err != nil {
		corpusSkipf(t, "corpus file missing: %v", err)
	}
	res := replay(t, path, testConfig(), 1.0)
	if len(res.sources) < 2 {
		t.Fatalf("decoy scan produced %d reported source(s); the capture should contain several", len(res.sources))
	}
	addrs := make([]string, 0, len(res.sources))
	for a := range res.sources {
		addrs = append(addrs, a.String())
	}
	sort.Strings(addrs)
	t.Logf("nmap -D produced %d indistinguishable scanning sources: %v", len(res.sources), addrs)
}

// requireCorpus skips the whole harness when the corpus has not been
// generated, but never lets that skip pass silently in CI.
//
// A test guarded by "skip if the input is missing" is how a broken path stays
// green forever. PORTSCAN_REQUIRE_CORPUS=1 in CI turns the skip into a
// failure, so the corpus must actually be present there.
func requireCorpus(t *testing.T) {
	t.Helper()
	entries, err := os.ReadDir(corpusDir())
	if err == nil && len(entries) > 0 {
		return
	}
	if os.Getenv("PORTSCAN_REQUIRE_CORPUS") == "1" {
		t.Fatalf("corpus missing at %s and PORTSCAN_REQUIRE_CORPUS=1: run testdata/generate_corpus.sh", corpusDir())
	}
	t.Skipf("corpus missing at %s; run testdata/generate_corpus.sh to generate it", corpusDir())
}

// corpusSkipf skips when a corpus file is missing, and fails instead under
// PORTSCAN_REQUIRE_CORPUS=1: requireCorpus only sees an empty directory, and
// a partial generation left files missing while every test that needed them
// skipped.
func corpusSkipf(t *testing.T, format string, args ...any) {
	t.Helper()
	if os.Getenv("PORTSCAN_REQUIRE_CORPUS") == "1" {
		t.Fatalf("PORTSCAN_REQUIRE_CORPUS=1 but "+format, args...)
	}
	t.Skipf(format, args...)
}
